59	    /** The status logs of the claims, by claim id, each oldest first. */
60	    @Transactional(readOnly = true)
61	    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
62	        if (of.isEmpty()) return Map.of();
63	        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
64	                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
65	    }
66	
67	    @Transactional
68	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
69	            String corrects) {
70	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
71	        RollupService.Snapshot before = rollup.snapshot(sheetId);
72	        LocalDate dated = date != null ? date : sheets.today(sheetId);
73	        refuseClosed(sheetId, dated);
74	        person.requireClaimable(dated);
75	        refuseBadCorrection(sheetId, personId, amount, corrects);
76	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
77	        claim.setDueBy(dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated), dated)));
78	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
79	        claim = claims.saveAndFlush(claim);
80	        log(user, person, claim);
81	        record("CLAIM_ADDED", user, person, claim, claim.getNumber());
82	        rollup.recordSince(sheetId, user, before);
83	        return claim;
84	    }
85	
86	    @Transactional
87	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
88	            String corrects) {
89	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
90	        LocalDate dated = date != null ? date : sheets.today(sheetId);
91	        refuseClosed(sheetId, claim.getDate());
92	        refuseClosed(sheetId, dated);
93	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
94	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
95	                .orElseThrow(PersonNotFoundException::new);
96	        person.requireClaimable(dated);
97	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
98	        RollupService.Snapshot before = rollup.snapshot(sheetId);
99	        claim.setAmount(amount);
100	        claim.setCorrects(corrects);
101	        claim.setDate(dated);
102	        claim.setNote(noteOf(note));
103	        claims.flush();
104	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
105	        rollup.recordSince(sheetId, user, before);
106	        return claim;
107	    }
108	
109	    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
110	     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
111	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
112	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
113	     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
114	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
115	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
116	     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
117	     * above the proof threshold in force on its date (refused before the clerk limit is considered). A voided claim keeps its number, if it had one. */
118	    @Transactional
119	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
120	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
121	        Action action = switch (next) {
122	            case OPEN -> Action.OPEN;
123	            case SETTLED -> Action.SETTLE;
124	            case VOID -> Action.VOID;
125	            default -> null;
126	        };
127	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
128	        refuseClosed(sheetId, claim.getDate());
129	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
130	            throw new ClaimStatusChangeException();
131	        }
132	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
133	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
134	        RollupService.Snapshot before = rollup.snapshot(sheetId);
135	        String number = claim.getNumber();
136	        if (next == ClaimStatus.OPEN) {
137	            number = nextNumber(sheetId, claim.getDate());
138	            claim.setOpenedBy(user);
139	        }
140	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
141	                .orElseThrow(PersonNotFoundException::new);
142	        if (next == ClaimStatus.SETTLED) {
143	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
144	            BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
145	            refuseUnproved(claim, due);
146	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
147	            else claim.setSettledDue(due);
148	        }
149	        claim.setStatus(next);
150	        claim.setNumber(number);
151	        claims.flush();
152	        log(user, person, claim);
153	        String event = switch (next) {
154	            case OPEN -> "CLAIM_OPENED";
155	            case PENDING -> "CLAIM_PENDING";
156	            case SETTLED -> "CLAIM_SETTLED";
157	            case VOID -> "CLAIM_VOIDED";
158	            case DRAFT -> throw new IllegalStateException();
159	        };
160	        if (next == ClaimStatus.SETTLED) {
161	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
162	        } else {
163	            record(event, user, person, claim, number);
164	        }
165	        rollup.recordSince(sheetId, user, before);
166	        return claim;
167	    }
168	
169	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
170	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
171	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
172	     * when the claim is dated in a closed period. */
173	    @Transactional
174	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
175	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
176	        refuseClosed(sheetId, claim.getDate());
177	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
178	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
179	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
180	                .orElseThrow(PersonNotFoundException::new);
181	        RollupService.Snapshot before = rollup.snapshot(sheetId);
182	        claim.setDeferredUntil(until);
183	        claims.flush();
184	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
185	        rollup.recordSince(sheetId, user, before);
186	        return claim;
187	    }
188	
189	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
190	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
191	     * Refused unless the claim is PENDING, when the user is not a steward or opened the claim, and when it
192	     * has no proofs and that due is above the proof threshold in force on its date. */
193	    @Transactional
194	    public Claim approve(String sheetId, String user, long claimId) {
195	        Claim claim = lockPending(sheetId, user, claimId);
196	        if (user.equals(claim.getOpenedBy())) throw new ClaimNotStewardException();
197	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
198	                .orElseThrow(PersonNotFoundException::new);
199	        RollupService.Snapshot before = rollup.snapshot(sheetId);
200	        BigDecimal figure = rollup.dueOf(claim, person);
201	        BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
202	        refuseUnproved(claim, due);
203	        claim.setSettledDue(due);
204	        claim.setStatus(ClaimStatus.SETTLED);
205	        claims.flush();
206	        log(user, person, claim);
207	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
208	        rollup.recordSince(sheetId, user, before);
209	        return claim;
210	    }
211	
212	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID, and when it is
213	     * dated in a closed period. */
214	    @Transactional
215	    public Claim addProof(String sheetId, String user, long claimId) {
216	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
217	        refuseClosed(sheetId, claim.getDate());
218	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
219	            throw new ClaimStatusChangeException();
220	        }
221	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
222	                .orElseThrow(PersonNotFoundException::new);
223	        claim.addProof();
224	        claims.flush();
225	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
226	        return claim;
227	    }
228	
229	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
230	     * by its person's last statement if that statement included it. Refused unless the claim is
231	     * PENDING, and when the user is not a steward. */
232	    @Transactional
233	    public Claim reject(String sheetId, String user, long claimId, String reason) {
234	        Claim claim = lockPending(sheetId, user, claimId);
235	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
236	                .orElseThrow(PersonNotFoundException::new);
237	        RollupService.Snapshot before = rollup.snapshot(sheetId);
238	        claim.setStatus(ClaimStatus.OPEN);
239	        claims.flush();
240	        log(user, person, claim);
241	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
242	        rollup.recordSince(sheetId, user, before);
243	        return claim;
244	    }
245	
246	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
247	     * number and date, loses any figure a statement bound it to (it is live again until its new
248	     * person's next statement), and is listed as its new person's newest claim. Refused when the user's
249	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
250	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
251	     * is dated after the new person's retirement date. */
252	    @Transactional
253	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
254	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
255	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
256	        refuseClosed(sheetId, claim.getDate());
257	        ClaimStatus status = claim.getStatus();
258	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
259	                || claim.isCorrection() || claim.getPersonId() == personId) {
260	            throw new ClaimReassignException();
261	        }
262	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
263	                .orElseThrow(PersonNotFoundException::new);
264	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
265	        to.requireClaimable(claim.getDate());
266	        RollupService.Snapshot before = rollup.snapshot(sheetId);
267	        claim.setPersonId(to.getId());
268	        claim.unbind();
269	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
270	        claims.flush();
271	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
272	        rollup.recordSince(sheetId, user, before);
273	        return claim;
274	    }
275	
276	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
277	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
278	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
279	     * steward, and when it is dated in a closed period. */
280	    @Transactional
281	    public Claim resettle(String sheetId, String user, long claimId) {
282	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
283	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
284	        refuseClosed(sheetId, claim.getDate());
285	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
286	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
287	                .orElseThrow(PersonNotFoundException::new);
288	        RollupService.Snapshot before = rollup.snapshot(sheetId);
289	        BigDecimal old = claim.getSettledDue();
290	        BigDecimal due = rollup.openShownOf(claim, person);
291	        claim.setSettledDue(due);
292	        claims.flush();
293	        log(user, person, claim);
294	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
295	        rollup.recordSince(sheetId, user, before);
296	        return claim;
297	    }
298	
299	    /** The PENDING claim, locked, for a steward to approve or reject. */
300	    private Claim lockPending(String sheetId, String user, long claimId) {
301	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
302	        refuseClosed(sheetId, claim.getDate());
303	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
304	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
305	        return claim;
306	    }
307	
308	    private static String dueText(BigDecimal due) {
309	        return due == null ? "n/a" : due.toPlainString();
310	    }
311	
312	    /** The figure the claim shows and totals now, without its late charge; null when it has no figure
313	     * (see {@link RollupService#figureOf}). */
314	    public BigDecimal figureOf(Claim claim, Person person) {
315	        return rollup.figureOf(claim, person);
316	    }
317	
318	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
319	     * no figure (see {@link RollupService#shownOf}). */
320	    public BigDecimal shownOf(Claim claim, Person person) {
321	        return rollup.shownOf(claim, person);
322	    }
323	
324	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
325	     * it shows now. */
326	    private void log(String user, Person person, Claim claim) {
327	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
328	                rollup.shownOf(claim, person)));
329	    }
330	
331	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
332	     * then any {@code extra} fields. */
333	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
334	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
335	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
336	                "date=" + claim.getDate()));
337	        if (number != null) fields.add("number=" + number);
338	        fields.addAll(List.of(extra));
339	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
340	    }
341	
342	    /** The number a claim dated {@code date} is given when opened now: within the period containing
343	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
344	     * period, otherwise the next sheet-wide number. */
345	    private String nextNumber(String sheetId, LocalDate date) {
346	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
347	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
348	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
349	                .findFirst()
350	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
351	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
352	    }
353	
354	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
355	     * the user is a clerk and the due is above the sheet's clerk limit. */
356	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
357	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
358	        BigDecimal limit = settings.clerkLimit(sheetId);
359	        return limit != null && due.compareTo(limit) > 0;
360	    }
361	
362	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
363	     * due is above the proof threshold in force on its date (a due that is n/a is within any threshold). */
364	    private void refuseUnproved(Claim claim, BigDecimal due) {
365	        if (due == null || claim.getProofs() > 0) return;
366	        BigDecimal threshold = settings.proofThresholdOn(claim.getSheetId(), claim.getDate());
367	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
368	    }
369	
370	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
371	     * the person, and a claim that names one without being a correction. */
372	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
373	        if (amount.signum() >= 0) {
374	            if (corrects != null) throw new ClaimCorrectionException();
375	            return;
376	        }
377	        if (corrects == null) throw new ClaimCorrectionException();
378	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
379	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
380	                .orElseThrow(ClaimCorrectionException::new);
381	    }
382	
383	    /** Refuse a change that touches {@code date} when a closed period of the sheet contains it. */
384	    private void refuseClosed(String sheetId, LocalDate date) {
385	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
386	    }
387	
388	    private static String noteOf(String note) {
389	        return note == null ? "" : note.trim();
390	    }
391	}
